async function woo(path,init={}){const u=new URL(`${storeUrl}/wp-json/wc/v3${path}`);u.searchParams.set("consumer_key",process.env.WOOCOMMERCE_CONSUMER_KEY);u.searchParams.set("consumer_secret",process.env.WOOCOMMERCE_CONSUMER_SECRET);const r=await fetch(u,{...init,headers:{"Content-Type":"application/json",...(init.headers||{})},signal:AbortSignal.timeout(90000),cache:"no-store"});const b=await r.json().catch(()=>null);if(!r.ok)throw new Error(`${path} ${r.status}: ${JSON.stringify(b)?.slice(0,500)}`);return b;}
async function categoryId(name){const a=await woo(`/products/categories?search=${encodeURIComponent(name)}&per_page=20`);const e=a.find(x=>x.name.toLowerCase()===name.toLowerCase());return e?.id||(await woo("/products/categories",{method:"POST",body:JSON.stringify({name})})).id;}
async function run(){const cat=await categoryId("Energía");for(const p of products){try{const found=await woo(`/products?sku=${encodeURIComponent(p.sku)}&status=any&per_page=20`);const existing=found[0];const isPanel=p.sku==="NEXO-SOLAR-FOLD-120W";const meta=[{key:"nexo_catalog_batch",value:"2026-09-04-energy"},{key:"nexo_source_price_usd",value:p.sourcePrice},{key:"nexo_supplier_commission_usd",value:p.supplierCommission||""},{key:"nexo_supplier_commission_visibility",value:"internal_only"},{key:"nexo_availability_confirmation",value:"required"},{key:"nexo_public_price_rule",value:"source_plus_15"},{key:"nexo_copy_style",value:"amazon-inspired-benefit-first"},{key:"nexo_verified_at",value:new Date().toISOString()}];for(const s of p.sources)meta.push({key:"nexo_research_source",value:s});const payload={name:p.name,slug:p.slug,type:isPanel?"variable":"simple",status:"publish",sku:p.sku,regular_price:isPanel?"":p.price,short_description:p.short,description:p.description,categories:[{id:cat}],manage_stock:Number.isInteger(p.stock),...(Number.isInteger(p.stock)?{stock_quantity:p.stock,stock_status:p.stock>0?"instock":"outofstock"}:{stock_status:"instock"}),...(!isPanel?{images:[{src:p.image,alt:p.name,name:p.name}]}:{}),attributes:isPanel?[{name:"Voltaje",visible:true,variation:true,options:["18V","36V"]},{name:"Potencia",visible:true,variation:false,options:["120W"]}]:[{name:"Garantía",visible:true,variation:false,options:["5 días por fallos del equipo"]},{name:"Entrega",visible:true,variation:false,options:["Domicilio incluido"]}],meta_data:meta};const saved=existing?await woo(`/products/${existing.id}`,{method:"PUT",body:JSON.stringify(payload)}):await woo("/products",{method:"POST",body:JSON.stringify(payload)});if(isPanel){const vars=await woo(`/products/${saved.id}/variations?per_page=100`);for(const v of ["18V","36V"]){const old=vars.find(x=>x.attributes?.some(a=>a.name==="Voltaje"&&a.option===v));const vp={regular_price:"108.00",status:"publish",stock_status:"instock",attributes:[{name:"Voltaje",option:v}]};old?await woo(`/products/${saved.id}/variations/${old.id}`,{method:"PUT",body:JSON.stringify(vp)}):await woo(`/products/${saved.id}/variations`,{method:"POST",body:JSON.stringify(vp)});}}console.log(`[nexo-energy-20260904] OK ${p.sku} -> ${saved.id} ${saved.permalink||""}`);}catch(e){console.error(`[nexo-energy-20260904] ERROR ${p.sku}:`,e instanceof Error?e.message:e);process.exitCode=1;}}}
run().catch(e=>{console.error(e);process.exitCode=1;});
